// Regenerates src/demo/example-files.ts from examples/policy and examples/policy-head, so `tokenyard demo` can run from
// the single bundled file without the examples directory. test/demo.test.ts fails when this file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const dir = (d) => Object.fromEntries(['policy.yaml', 'prices.yaml', 'keys.yaml'].map((f) => [f, readFileSync(join(root, 'examples', d, f), 'utf8')]));
const out = [
  '// Generated by scripts/gen-demo-files.mjs from examples/policy and examples/policy-head. Do not edit.',
  `export const EXAMPLE_BASE: Record<string, string> = ${JSON.stringify(dir('policy'), null, 2)};`,
  '',
  `export const EXAMPLE_HEAD: Record<string, string> = ${JSON.stringify(dir('policy-head'), null, 2)};`,
  '',
].join('\n');
writeFileSync(join(root, 'src', 'demo', 'example-files.ts'), out);
